import { t } from './i18n.mjs';
import { categoryLabel } from './story-categories.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat(t("en-US","vi-VN","ko-KR")).format(n)+' ₫';
let api,demo=false;
const examples=()=>[{id:'DEBT001',title:t("Final semester tuition","Học phí kỳ cuối","마지막 학기 등록금"),category:'Học tập',story:t("The remaining tuition needed to finish my studies and graduate.","Khoản học phí còn lại cần hoàn thành để tiếp tục việc học và tốt nghiệp.","학업을 마치고 졸업하기 위해 내야 하는 남은 등록금입니다."),amount:14000000,pledged:0,paid:4000000,documents:2,status:'Đang nhận hỗ trợ'}, {id:'DEBT002',title:t("Family medical expenses","Chi phí y tế gia đình","가족 의료비"),category:'Y tế',story:t("Unexpected treatment costs that I need help paying.","Khoản chi phí điều trị phát sinh ngoài dự kiến, cần hỗ trợ thanh toán.","예상치 못하게 발생한 치료비를 납부하는 데 도움이 필요합니다."),amount:18500000,pledged:0,paid:0,documents:1,status:'Chờ xét duyệt'}];
const icons={wallet:'<rect x="3" y="6" width="17" height="15" rx="2"/><path d="M3 9V5a2 2 0 0 1 2-2h12v3M20 12h-5v5h5M17 14.5h.01"/>',heart:'<path d="M12 7c-4-5-10 1 0 8 10-7 4-13 0-8Z"/><path d="m3 17 3-2 5 3 5-2c3-1 4 1 2 2l-7 4-6-2-2 1"/>',files:'<rect x="4" y="7" width="12" height="14" rx="2"/><path d="M9 7V4a2 2 0 0 1 2-2h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2h-2"/>',education:'<path d="m2 8 10-5 10 5-10 5L2 8Zm4 3v6c4 4 8 4 12 0v-6M22 8v8"/>',medical:'<path d="M12 21C-7 10 4-3 12 6c8-9 19 4 0 15Z"/><path d="M5 12h4l2-4 3 8 2-4h3"/>',clip:'<path d="M8 10v8a4 4 0 0 0 8 0V6a3 3 0 0 0-6 0v11a1 1 0 0 0 2 0V8"/>'};
const icon=(name)=>`<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.wallet}</svg>`;
export function initDebts(callbacks){api=callbacks;const root=document.createElement('section');root.id='debts-page';root.setAttribute('aria-label',t("My debt","Khoản nợ của tôi","내 채무"));document.body.append(root);root.addEventListener('click',ev=>{const button=ev.target.closest('[data-debt]');if(!button)return;switch(button.dataset.debt){case 'add':demo=false;renderDebts();api.add();break;case 'detail':details(button.dataset.id);break;case 'profile':document.body.classList.remove('debts-mode');api.profile();break;case 'messages':document.body.classList.remove('debts-mode');api.messages();break;case 'back':demo=false;document.body.classList.remove('debts-mode');api.back();break;case 'demo':demo=!demo;renderDebts();break;}});}
export function showDebts(){document.body.classList.remove('onboarding','broke-mode','messages-mode','registration-mode','bros-join-mode','card-wizard-mode');document.body.classList.add('debts-mode');renderDebts();window.scrollTo(0,0);document.querySelector('#debts-title')?.focus({preventScroll:true});}
export function renderDebts(){const root=document.querySelector('#debts-page');if(!root)return;const posts=demo?examples():api.getPosts(),total=posts.reduce((sum,p)=>sum+p.amount,0),paid=demo?4000000:0,pledged=posts.reduce((sum,p)=>sum+(p.pledged||0),0);root.innerHTML=`<div class="debts-shell"><div class="debts-header"><a class="debts-brand" href="#" data-debt="profile"><img src="assets/debtfreelately-mark-clean.png" alt=""><span><strong>DebtFreeLately.</strong><small>${t("BROKE DASHBOARD","BẢNG ĐIỀU KHIỂN BROKE","BROKE 대시보드")}</small></span></a><div class="debts-header-actions"><button data-debt="profile">${t("Profile","Trang cá nhân","프로필")}</button><button data-debt="messages">${t("Messages","Tin nhắn","메시지")}</button><span>${t("My Debts","Khoản nợ của tôi","내 채무")}</span></div></div><div class="debts-page-heading"><div><h1 id="debts-title" tabindex="-1">${t("My Debts","Khoản nợ của tôi","내 채무")}</h1><p>${t("Manage debts and requests for support","Quản lý khoản nợ và yêu cầu hỗ trợ","채무 및 지원 요청 관리")}</p></div><button class="debts-add" data-debt="add"><span>＋</span> ${t("Add debt","Thêm khoản nợ","채무 추가")}</button></div>${demo?'<div class="debts-demo-notice">'+t("SAMPLE DATA · The amounts, statuses and documents below are for illustration only.","ĐANG XEM DỮ LIỆU MẪU · Các số tiền, trạng thái và tài liệu dưới đây chỉ minh họa thiết kế.","예시 데이터 · 아래 금액, 상태 및 문서는 화면 설명용입니다.")+'</div>':''}<div class="debt-statistics"><div>${icon('wallet')}<strong>${money(total)}</strong><span>${t("Total debt","Tổng khoản nợ","총 채무")}</span></div><div>${icon('heart')}<strong>${money(paid)}</strong><span>${t("Support received","Đã được giúp","받은 지원")} ${demo?t("· Sample","· Mẫu","· 예시"):''}</span></div><div>${icon('files')}<strong>${String(posts.length).padStart(2,'0')}</strong><span>${t("Debt records","Hồ sơ khoản nợ","채무 기록")}</span></div></div><div class="debts-list-title"><h2>${t("Debt list","Danh sách khoản nợ","채무 목록")}</h2><span>${posts.length} ${t("records","hồ sơ","건")}</span></div><div class="debts-list">${posts.length?posts.map(p=>card(p,demo)).join(''):`<div class="debts-empty"><div>${icon('wallet')}</div><h3>${t("A fresh start begins here.","Một khởi đầu mới, từ đây.","여기서 새로운 시작을.")}</h3><p>${t("You haven’t recorded any debts yet.","Bạn chưa có khoản nợ nào được ghi lại.","아직 기록한 채무가 없습니다.")}<br>${t("Add your first debt to start tracking it and sharing your story.","Thêm khoản nợ đầu tiên để bắt đầu quản lý và chia sẻ câu chuyện.","첫 채무를 추가해 관리하고 이야기를 공유하세요.")}</p><button class="debts-add" data-debt="add">${t("＋ Add your first debt","＋ Thêm khoản nợ đầu tiên","＋ 첫 채무 추가")}</button></div>`}</div><div class="debts-bottom"><p>${demo?t("Sample data.","Dữ liệu minh họa.","예시 데이터입니다."):t(`Data stored in this browser · ${money(pledged)} pledged, payment pending.`,`Dữ liệu lưu trên trình duyệt · ${money(pledged)} cam kết, chưa thanh toán.`,`브라우저에 저장된 데이터 · ${money(pledged)} 지원 약속, 미지급`)}</p><button data-debt="demo">${demo?t("← Back to my debts","← Quay lại khoản nợ của tôi","← 내 채무로 돌아가기"):t("View sample layout ↗","Xem giao diện mẫu ↗","예시 화면 보기 ↗")}</button></div><button class="debts-back" data-debt="back">${t("← Switch roles","← Đổi vai trò","← 역할 전환")}</button></div>`;}
function card(p,sample){const paid=sample?(p.paid||0):0,percent=Math.min(100,paid/p.amount*100),label=sample?(p.status==='Đang nhận hỗ trợ'?t("Receiving support","Đang nhận hỗ trợ","지원받는 중"):t("Pending review","Chờ xét duyệt","심사 대기 중")):t("Unverified","Chưa xác minh","미인증"),isOpen=sample&&p.status==='Đang nhận hỗ trợ';return `<article class="debt-record"><div class="debt-record-heading"><div class="debt-record-icon">${icon(p.category==='Học tập'?'education':p.category==='Y tế'?'medical':'wallet')}</div><div><h3>${esc(p.title)}</h3><p>${esc(categoryLabel(p.category))} · #${sample?p.id:'DEBT-'+esc(p.id.slice(0,8).toUpperCase())}</p></div><span class="debt-status ${isOpen?'open':''}">${esc(label)}</span></div><p class="debt-description">${esc(p.story)}</p><div class="debt-values"><div><small>${t("Original outstanding balance","Số tiền còn nợ ban đầu","초기 채무 잔액")}</small><strong>${money(p.amount)}</strong></div>${paid?`<div><small>${t("Support received · Sample","Đã hỗ trợ · Mẫu","받은 지원 · 예시")}</small><strong>${money(paid)}</strong></div>`:!sample&&p.pledged?`<div><small>${t("Pledged · Payment pending","Cam kết · Chưa thanh toán","지원 약속 · 미지급")}</small><strong>${money(p.pledged)}</strong></div>`:''}</div>${isOpen?`<div class="debt-record-progress" role="progressbar" aria-label="${t("Sample support progress","Tiến độ hỗ trợ minh họa","지원 진행 상황 예시")}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(percent)}"><div style="width:${percent}%"></div></div>`:''}<div class="debt-record-bottom"><span>${icon('clip')}${sample?t(`${p.documents} documents · Sample`,`${p.documents} tài liệu · Minh họa`,`문서 ${p.documents}개 · 예시`):t("No documents attached","Chưa có tài liệu đính kèm","첨부된 문서 없음")}</span><button data-debt="detail" data-id="${esc(p.id)}">${t("Details →","Chi tiết →","상세 보기 →")}</button></div></article>`;}
function details(id){const p=(demo?examples():api.getPosts()).find(p=>p.id===id);if(!p)return;api.modal(`<div class="eyebrow">${demo?t("SAMPLE RECORD","HỒ SƠ MINH HỌA","예시 기록"):t("DEBT RECORD · UNVERIFIED","HỒ SƠ KHOẢN NỢ · CHƯA XÁC MINH","채무 기록 · 미인증")}</div><h2>${esc(p.title)}</h2><p>${esc(categoryLabel(p.category))}</p><p class="detail-story">${esc(p.story)}</p><div class="info-box">${t("Debt:","Khoản nợ:","채무:")} <strong>${money(p.amount)}</strong><br>${demo?t(`Sample support: ${money(p.paid||0)}`,`Hỗ trợ minh họa: ${money(p.paid||0)}`,`지원 예시: ${money(p.paid||0)}`):t(`Pledged: ${money(p.pledged||0)} · Payment pending`,`Cam kết: ${money(p.pledged||0)} · Chưa thanh toán`,`지원 약속: ${money(p.pledged||0)} · 미지급`)}</div><p>${demo?t("These amounts and documents are for illustration only.","Đây là dữ liệu mẫu, không có tiền hoặc tài liệu thật.","이 금액과 문서는 예시입니다."):t("Records are stored in this browser. Document submission and verification are coming later.","Hồ sơ chỉ lưu trên trình duyệt. Phần nộp và xác minh tài liệu sẽ được bổ sung sau.","기록은 이 브라우저에 저장됩니다. 문서 제출 및 인증은 추후 제공됩니다.")}</p>${demo?'':'<button class="dark" id="debt-edit">'+t("Edit debt","Chỉnh sửa khoản nợ","채무 수정")+'</button><button class="registration-alt" id="debt-delete">'+t("Delete debt","Xóa khoản nợ","채무 삭제")+'</button>'}`);if(!demo){document.querySelector('#debt-edit').onclick=()=>{api.close();api.edit(id);};document.querySelector('#debt-delete').onclick=()=>{api.close();api.remove(id);};}}


